import json
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = "http://localhost:8080"
RANGE_START = datetime(2025, 3, 1, tzinfo=timezone.utc)
RANGE_END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive: 31 May inclusive
REGIONS = ["north", "south", "east", "west"]

token = None
log = []


def note(msg):
    print(msg, file=sys.stderr, flush=True)


def get_token():
    global token
    req = urllib.request.Request(BASE + "/token", method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        token = json.load(r)["token"]
    return token


def wait_seconds(err, body):
    ra = err.headers.get("Retry-After") if err.headers else None
    if ra:
        try:
            return float(ra)
        except ValueError:
            pass
    try:
        j = json.loads(body)
        for k in ("retry_after", "retry_after_seconds", "wait", "wait_seconds"):
            if k in j:
                return float(j[k])
    except Exception:
        pass
    return None


def request(path, auth=True):
    """GET with retries. Honours rate-limit waits, refreshes expired tokens,
    and retries transient failures. Gives up after many attempts."""
    attempts = 0
    while True:
        attempts += 1
        if attempts > 60:
            raise RuntimeError(f"giving up on {path} after {attempts} attempts")
        headers = {}
        if auth:
            if token is None:
                get_token()
            headers["Authorization"] = "Bearer " + token
        req = urllib.request.Request(BASE + path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", "replace")
            if e.code == 401 and auth:
                note(f"401 on {path}: refreshing token")
                get_token()
                continue
            if e.code == 429 or e.code == 503:
                w = wait_seconds(e, body)
                w = w if w is not None else 5.0
                note(f"{e.code} on {path}: waiting {w}s (body: {body[:200]!r})")
                time.sleep(w)
                continue
            if e.code == 404:
                return None
            if 500 <= e.code < 600:
                note(f"{e.code} on {path}: retrying in 2s")
                time.sleep(2)
                continue
            raise RuntimeError(f"HTTP {e.code} on {path}: {body[:300]}")
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            note(f"network error on {path}: {e}; retrying in 2s")
            time.sleep(2)


def fetch_all_orders():
    orders_seen = {}
    dupes = 0
    pages = 0
    total_pages = None
    path = "/orders?page=1"
    while path:
        data = request(path)
        pages += 1
        total_pages = data.get("total_pages", total_pages)
        for item in data["items"]:
            oid = item["id"]
            if oid in orders_seen:
                dupes += 1
                if orders_seen[oid] != item:
                    note(f"NOTE: duplicate id {oid} with differing content; keeping first")
            else:
                orders_seen[oid] = item
        note(f"page {data.get('page')} of {total_pages}: {len(data['items'])} items")
        path = data.get("next")
    return orders_seen, dupes, pages, total_pages


def main():
    orders, dupes, pages, total_pages = fetch_all_orders()
    note(f"fetched {pages} pages (reported total_pages={total_pages}), "
         f"{len(orders)} distinct orders, {dupes} duplicate listings")

    customer_cache = {}

    def customer(cid):
        if cid not in customer_cache:
            c = request(f"/customers/{cid}")
            if c is None:
                raise RuntimeError(f"customer {cid} not found (404)")
            customer_cache[cid] = c
        return customer_cache[cid]

    total = 0
    count = 0
    by_region = {r: 0 for r in REGIONS}
    odd = []

    for oid, o in orders.items():
        ts_raw = o["placed_at"]
        ts = datetime.fromisoformat(ts_raw.replace("Z", "+00:00"))
        if ts.tzinfo is None:
            odd.append(f"{oid}: naive timestamp {ts_raw}")
            continue
        ts_utc = ts.astimezone(timezone.utc)
        if o["status"] != "shipped":
            continue
        if not (RANGE_START <= ts_utc < RANGE_END):
            continue
        cust = customer(o["customer_id"])
        pct = cust["discount_pct"]
        amount = Decimal(o["amount_cents"])
        discounted = (amount * (100 - Decimal(pct)) / 100).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP)
        cents = int(discounted)
        region = cust["region"]
        if region not in by_region:
            raise RuntimeError(f"unexpected region {region!r} for {oid}")
        by_region[region] += cents
        total += cents
        count += 1

    if odd:
        note("odd timestamps: " + "; ".join(odd))

    result = {
        "total_cents": total,
        "order_count": count,
        "duplicates_skipped": dupes,
        "by_region": by_region,
    }
    assert sum(by_region.values()) == total
    with open("/workspace/result.json", "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    note("wrote /workspace/result.json")
    print(json.dumps(result, indent=2))
    note(f"customers looked up: {len(customer_cache)}, total orders: {len(orders)}")


if __name__ == "__main__":
    main()

